interface User { id: string; name: string; }
interface Admin { id: string; name: string; role: string; }

function greet(u: User) {
  return `Hello ${u.name}`;
}

const admin: Admin = { id: "1", name: "Ada", role: "super" };
greet(admin); // OK — Admin has User's required fields

